//! go-file: pkg/expression/builtin.go
//!
//! The evaluation framework of N4 §3.2–3.4: built-in function signatures, the two drivers
//! generated by `#[eval_fn]`, and the vector evaluation of an expression compiled to RPN.
//!
//! - A signature (Go's `builtinXxxSig` type) is a static [`SigDesc`]; a function node holds a
//!   [`BuiltinFunc`] = the signature + Go's `baseBuiltinFunc` fields.
//! - The body is written once, from Go's row version (`evalXxx`); `#[eval_fn]` generates the
//!   row driver and the vector driver ([`SigDrivers`]). Go's `vecEvalXxx` is not ported
//!   (M-EVAL); the vector driver reproduces its visible behavior (all arguments evaluated
//!   column by column first, NULL rows skipped).
//! - [`RpnProgram`] is the post-order form of an expression for the vector driver; it borrows
//!   the input chunk's columns instead of copying them (N4 §3.4).

#![allow(non_upper_case_globals, clippy::needless_range_loop)]

pub mod rt;

use smallvec::SmallVec;
use std::any::Any;
use std::borrow::Cow;
use std::cell::{RefCell, RefMut};

use tidb_base::Error;
use tidb_base::mysql;
use tidb_chunk::{Chunk, Column, Row};
use tidb_parser::gocharset;
use tidb_parser::types::{
    ETDatetime, ETDecimal, ETDuration, ETInt, ETJson, ETReal, ETString, ETTimestamp,
    ETVectorFloat32, EvalType,
};
use tidb_types::collate::{self, Collator};
use tidb_types::etc::FieldType;
use tidb_types::json::BinaryJSON;
use tidb_types::mydecimal::MyDecimal;
use tidb_types::time::{Duration, Time};
use tidb_types::vector::VectorFloat32;

use crate::collation::CollationInfo;
use crate::context::EvalContext;
use crate::expression::{EvalState, Expr, ExprRef};

/// The row driver of a signature returning `T` (`evalXxx`).
pub type RowFn<T> =
    fn(&BuiltinFunc, &dyn EvalContext, &EvalState, Row<'_>) -> Result<Option<T>, Error>;
/// The vector driver of a signature: `n` rows, the evaluated argument columns, the result.
pub type VecFn =
    fn(&BuiltinFunc, &dyn EvalContext, usize, &[&Column], &mut Column) -> Result<(), Error>;

/// The evaluation types a signature's vector driver reads its arguments as (Go: which
/// `args[i].VecEvalXxx` its `vecEvalXxx` calls); empty for `lazy` bodies, which read each
/// argument as its own evaluation type.
pub type ArgEvalTypes = &'static [EvalType];

/// The drivers `#[eval_fn]` generates for one signature: one variant per evaluation type
/// (a Go signature implements the `evalXxx`/`vecEvalXxx` pair of its result type).
#[derive(Clone, Copy)]
pub enum SigDrivers {
    /// `evalInt`.
    Int {
        row: RowFn<i64>,
        vec: VecFn,
        args: ArgEvalTypes,
    },
    /// `evalReal`.
    Real {
        row: RowFn<f64>,
        vec: VecFn,
        args: ArgEvalTypes,
    },
    /// `evalDecimal`.
    Decimal {
        row: RowFn<MyDecimal>,
        vec: VecFn,
        args: ArgEvalTypes,
    },
    /// `evalString`.
    String {
        row: RowFn<Vec<u8>>,
        vec: VecFn,
        args: ArgEvalTypes,
    },
    /// `evalTime`.
    Time {
        row: RowFn<Time>,
        vec: VecFn,
        args: ArgEvalTypes,
    },
    /// `evalDuration`.
    Duration {
        row: RowFn<Duration>,
        vec: VecFn,
        args: ArgEvalTypes,
    },
    /// `evalJSON`.
    Json {
        row: RowFn<BinaryJSON<'static>>,
        vec: VecFn,
        args: ArgEvalTypes,
    },
    /// `evalVectorFloat32`.
    VectorFloat32 {
        row: RowFn<VectorFloat32<'static>>,
        vec: VecFn,
        args: ArgEvalTypes,
    },
    /// No evaluation: a signature that is only built and inspected (planner-only signatures,
    /// and the descriptor-only signatures of tests). Every `evalXxx` returns Go's
    /// `baseBuiltinFunc` error.
    None,
}

impl SigDrivers {
    /// The evaluation type of the result (`None` for [`SigDrivers::None`]).
    // glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
    pub fn eval_type(&self) -> Option<EvalType> {
        Some(match self {
            SigDrivers::Int { .. } => ETInt,
            SigDrivers::Real { .. } => ETReal,
            SigDrivers::Decimal { .. } => ETDecimal,
            SigDrivers::String { .. } => ETString,
            SigDrivers::Time { .. } => ETDatetime,
            SigDrivers::Duration { .. } => ETDuration,
            SigDrivers::Json { .. } => ETJson,
            SigDrivers::VectorFloat32 { .. } => ETVectorFloat32,
            SigDrivers::None => return None,
        })
    }

    /// The type argument `i` is read as (`None`: its own evaluation type).
    // glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
    pub fn arg_eval_type(&self, i: usize) -> Option<EvalType> {
        match *self {
            SigDrivers::Int { args, .. }
            | SigDrivers::Real { args, .. }
            | SigDrivers::Decimal { args, .. }
            | SigDrivers::String { args, .. }
            | SigDrivers::Time { args, .. }
            | SigDrivers::Duration { args, .. }
            | SigDrivers::Json { args, .. }
            | SigDrivers::VectorFloat32 { args, .. } => args.get(i).copied(),
            SigDrivers::None => None,
        }
    }

    // glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
    fn vec(&self) -> Option<VecFn> {
        match *self {
            SigDrivers::Int { vec, .. }
            | SigDrivers::Real { vec, .. }
            | SigDrivers::Decimal { vec, .. }
            | SigDrivers::String { vec, .. }
            | SigDrivers::Time { vec, .. }
            | SigDrivers::Duration { vec, .. }
            | SigDrivers::Json { vec, .. }
            | SigDrivers::VectorFloat32 { vec, .. } => Some(vec),
            SigDrivers::None => None,
        }
    }
}

/// A built-in function signature: Go's concrete `builtinXxxSig` type (N4 §3.1).
pub struct SigDesc {
    /// The Go type name, e.g. `builtinArithmeticPlusIntSig`.
    pub name: &'static str,
    /// `tipb.ScalarFuncSig` code set by `setPbCode`.
    pub pb_code: i32,
    /// Go's `vectorized()` (`baseBuiltinFunc.vectorized` returns false).
    pub vectorized: bool,
    /// The drivers.
    pub drivers: SigDrivers,
}

impl std::fmt::Debug for SigDesc {
    // glue: trait impl
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(self.name)
    }
}

/// `unsafe.Sizeof(baseBuiltinFunc{})` on 64-bit targets (spec §4, measured by the govec
/// generator).
pub(crate) const emptyBaseBuiltinFunc: i64 = 152;
/// `unsafe.Sizeof(sync.Once{})`.
pub(crate) const onceSize: i64 = 12;

/// A function node's signature with the `baseBuiltinFunc` fields (N4 §3.1).
///
/// Not kept from Go: `bufAllocator` and `childrenVectorizedOnce` (the vector driver pools
/// its columns in [`RpnState`], M-POOL), so `isChildrenVectorized` is computed on each call.
#[derive(Clone)]
pub struct BuiltinFunc {
    /// The signature (Go's concrete type).
    pub sig: &'static SigDesc,
    /// `args`.
    pub args: Vec<ExprRef>,
    /// `tp`: the result type.
    pub tp: FieldType,
    /// `pbCode`.
    pub pb_code: i32,
    /// `ctor`: the collator, `nil` until `SetCollator`.
    ctor: Option<&'static dyn Collator>,
    /// The embedded `collationInfo`.
    pub collation_info: CollationInfo,
    /// `baseBuiltinCastFunc.inUnion` for the CAST signatures that embed `baseBuiltinCastFunc`
    /// (D08.8); `None` for every other signature (Go's `baseBuiltinFunc` has no such field).
    pub in_union: Option<bool>,
}

impl std::fmt::Debug for BuiltinFunc {
    // glue: trait impl
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("BuiltinFunc")
            .field("sig", &self.sig)
            .field("args", &self.args)
            .field("tp", &self.tp)
            .field("pb_code", &self.pb_code)
            .field("collation_info", &self.collation_info)
            .finish()
    }
}

macro_rules! row_dispatch {
    ($name:ident, $variant:ident, $t:ty, $go:literal) => {
        #[doc = concat!("`", $go, "`: the row driver.")]
        pub fn $name(
            &self,
            ctx: &dyn EvalContext,
            st: &EvalState,
            row: Row<'_>,
        ) -> Result<Option<$t>, Error> {
            match self.sig.drivers {
                SigDrivers::$variant { row: f, .. } => f(self, ctx, st, row),
                _ => Err(Error::plain(concat!(
                    "baseBuiltinFunc.",
                    $go,
                    "() should never be called, please contact the TiDB team for help"
                ))),
            }
        }
    };
}

impl BuiltinFunc {
    /// A `baseBuiltinFunc` not yet embedded in a concrete signature (the fields a
    /// `newBaseBuiltinFunc*` constructor starts from); see [`BuiltinFunc::with_sig`].
    // glue: baseBuiltinFunc{args: args, tp: tp} literal of the newBaseBuiltinFunc* constructors
    pub(crate) fn base(args: Vec<ExprRef>, tp: FieldType) -> BuiltinFunc {
        BuiltinFunc {
            sig: &crate::builtin::baseBuiltinFuncSig,
            args,
            tp,
            pb_code: 0,
            ctor: None,
            collation_info: CollationInfo::default(),
            in_union: None,
        }
    }

    /// Embeds the base in the signature `sig` (Go's `&builtinXxxSig{bf}`) and sets the
    /// signature's `tipb` code (Go's `sig.setPbCode(...)`).
    // glue: struct literal &builtinXxxSig{bf} + setPbCode of a function class
    pub fn with_sig(mut self, sig: &'static SigDesc) -> BuiltinFunc {
        self.sig = sig;
        self.pb_code = sig.pb_code;
        self
    }

    /// A signature over `args` with the given derived type and collation (tests and the
    /// descriptor-only signatures of govec; function classes use `new_base_builtin_func*`).
    // glue: descriptor-only construction used by tests
    pub fn new(
        sig: &'static SigDesc,
        args: Vec<ExprRef>,
        tp: FieldType,
        charset: &str,
        collation: &str,
    ) -> BuiltinFunc {
        let mut collation_info = CollationInfo::default();
        collation_info.set_charset_and_collation(charset, collation);
        BuiltinFunc {
            sig,
            args,
            tp,
            pb_code: sig.pb_code,
            ctor: Some(collate::get_collator(collation)),
            collation_info,
            in_union: None,
        }
    }

    /// PbCode returns PbCode of this signature.
    // go: baseBuiltinFunc.PbCode L1
    pub fn pb_code(&self) -> i32 {
        self.pb_code
    }

    /// `b.collator()`. Panics where Go dereferences a nil collator.
    // go: baseBuiltinFunc.collator L1
    #[inline]
    pub fn collator(&self) -> &'static dyn Collator {
        self.ctor.expect("nil collator")
    }

    /// `SetCollator`.
    // go: baseBuiltinFunc.setCollator L1
    pub fn set_collator(&mut self, ctor: &'static dyn Collator) {
        self.ctor = Some(ctor);
    }

    /// `b.args[i]`.
    #[inline]
    // glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
    pub fn arg(&self, i: usize) -> &Expr {
        &self.args[i]
    }

    // go: baseBuiltinFunc.getArgs L1
    #[inline]
    pub fn get_args(&self) -> &[ExprRef] {
        &self.args
    }

    // go: baseBuiltinFunc.getRetTp L1
    pub fn get_ret_tp(&mut self) -> &FieldType {
        if self.tp.eval_type() == ETString {
            if self.tp.get_flen() >= mysql::MaxBlobWidth {
                self.tp.set_type(mysql::TypeLongBlob);
            } else if self.tp.get_flen() >= 65536 {
                self.tp.set_type(mysql::TypeMediumBlob);
            }
            if self.tp.get_charset().is_empty() {
                let (charset, collate) = gocharset::get_default_charset_and_collate();
                self.tp.set_charset(charset);
                self.tp.set_collate(collate);
            }
        }
        &self.tp
    }

    // go: baseBuiltinFunc.vectorized L2 (the signature's own vectorized() is SigDesc.vectorized)
    pub fn vectorized(&self) -> bool {
        self.sig.vectorized
    }

    /// Go caches the answer in `childrenVectorizedOnce`; the arguments of a built signature
    /// do not change, so computing it again gives the same answer.
    // go: baseBuiltinFunc.isChildrenVectorized L2 (no once/bufAllocator, M-POOL)
    pub fn is_children_vectorized(&self) -> bool {
        self.args.iter().all(|arg| arg.vectorized())
    }

    // go: baseBuiltinFunc.equal L1
    pub fn equal(&self, ctx: &dyn EvalContext, fun: &BuiltinFunc) -> bool {
        let fun_args = fun.get_args();
        if fun_args.len() != self.args.len() {
            return false;
        }
        for i in 0..self.args.len() {
            if !self.args[i].equal(ctx, &fun_args[i]) {
                return false;
            }
        }
        true
    }

    /// `Clone()` of a signature: `cloneFrom` the base, then copy the signature's own fields.
    /// The argument nodes are immutable and shared (M-EXPR), so cloning the list is the
    /// deep copy Go makes.
    // go: baseBuiltinFunc.Clone L2 (a signature's Clone is BuiltinFunc's; Go's base method only panics and is never reached)
    // go: baseBuiltinFunc.cloneFrom L2 (args shared, M-EXPR; ctor.Clone() of the stateless collators is the same collator)
    // go: baseBuiltinCastFunc.cloneFrom L2 (inUnion is a field of the BuiltinFunc)
    pub fn clone_from_base(&self) -> BuiltinFunc {
        self.clone()
    }

    /// MemoryUsage returns the memory usage of baseBuiltinFunc. Go adds `bufAllocator` once
    /// `isChildrenVectorized` has created it; tidb-rs has no per-signature pool (spec §4).
    // go: baseBuiltinFunc.MemoryUsage L2 (no bufAllocator, spec §4)
    pub fn memory_usage(&self) -> i64 {
        let mut sum = emptyBaseBuiltinFunc + self.collation_info.strings_len();
        sum += self.tp.memory_usage();
        sum += onceSize;
        for e in &self.args {
            sum += e.memory_usage();
        }
        sum
    }

    // go: baseBuiltinFunc.evalInt L2 (dispatch: the error when the signature has no evalInt driver)
    row_dispatch!(eval_int, Int, i64, "evalInt");
    // go: baseBuiltinFunc.evalReal L2 (dispatch: the error when the signature has no evalReal driver)
    row_dispatch!(eval_real, Real, f64, "evalReal");
    // go: baseBuiltinFunc.evalDecimal L2 (dispatch: the error when the signature has no evalDecimal driver)
    row_dispatch!(eval_decimal, Decimal, MyDecimal, "evalDecimal");
    // go: baseBuiltinFunc.evalString L2 (dispatch: the error when the signature has no evalString driver)
    row_dispatch!(eval_string, String, Vec<u8>, "evalString");
    // go: baseBuiltinFunc.evalTime L2 (dispatch: the error when the signature has no evalTime driver)
    row_dispatch!(eval_time, Time, Time, "evalTime");
    // go: baseBuiltinFunc.evalDuration L2 (dispatch: the error when the signature has no evalDuration driver)
    row_dispatch!(eval_duration, Duration, Duration, "evalDuration");
    // go: baseBuiltinFunc.evalJSON L2 (dispatch: the error when the signature has no evalJSON driver)
    row_dispatch!(eval_json, Json, BinaryJSON<'static>, "evalJSON");
    // go: baseBuiltinFunc.evalVectorFloat32 L2 (dispatch: the error when the signature has no evalVectorFloat32 driver)
    row_dispatch!(
        eval_vector_float32,
        VectorFloat32,
        VectorFloat32<'static>,
        "evalVectorFloat32"
    );

    /// `vecEvalXxx` of the result type `et` on `n` rows of evaluated arguments.
    // go: baseBuiltinFunc.vecEvalInt L2 (dispatch: the error when the signature has no vector driver for Int)
    // go: baseBuiltinFunc.vecEvalReal L2 (dispatch: the error when the signature has no vector driver for Real)
    // go: baseBuiltinFunc.vecEvalString L2 (dispatch: the error when the signature has no vector driver for String)
    // go: baseBuiltinFunc.vecEvalDecimal L2 (dispatch: the error when the signature has no vector driver for Decimal)
    // go: baseBuiltinFunc.vecEvalTime L2 (dispatch: the error when the signature has no vector driver for Time)
    // go: baseBuiltinFunc.vecEvalDuration L2 (dispatch: the error when the signature has no vector driver for Duration)
    // go: baseBuiltinFunc.vecEvalJSON L2 (dispatch: the error when the signature has no vector driver for JSON)
    // go: baseBuiltinFunc.vecEvalVectorFloat32 L2 (dispatch: the error when the signature has no vector driver for VectorFloat32)
    pub fn vec_eval(
        &self,
        ctx: &dyn EvalContext,
        et: EvalType,
        n: usize,
        cols: &[&Column],
        result: &mut Column,
    ) -> Result<(), Error> {
        match self.sig.drivers.vec() {
            Some(f) if self.sig.drivers.eval_type() == Some(normalize_et(et)) => {
                f(self, ctx, n, cols, result)
            }
            _ => Err(Error::plain(format!(
                "baseBuiltinFunc.vecEval{}() should never be called, please contact the TiDB team for help",
                vec_eval_name(et)
            ))),
        }
    }
}

// glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
fn normalize_et(et: EvalType) -> EvalType {
    if et == ETTimestamp { ETDatetime } else { et }
}

// glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
fn vec_eval_name(et: EvalType) -> &'static str {
    match et {
        ETInt => "Int",
        ETReal => "Real",
        ETDecimal => "Decimal",
        ETString => "String",
        ETDatetime | ETTimestamp => "Time",
        ETDuration => "Duration",
        ETJson => "JSON",
        _ => "VectorFloat32",
    }
}

/// What a body sees of its signature in one driver call: the [`BuiltinFunc`] (through
/// `Deref`) and `b.args[i].GetType(ctx)`.
///
/// Bodies take `f: &impl SigView`, so each driver gets its own copy of the body:
/// [`RowSig`] asks the argument when the body does (Go's row versions), [`VecSig`] reads the
/// types once per chunk (Go's vector versions do the same; the type of an argument cannot
/// change within a statement) and keeps them where the compiler can hold them in registers
/// for the whole loop.
pub trait SigView: std::ops::Deref<Target = BuiltinFunc> {
    /// `b.args[i].GetType(ctx)`.
    // glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
    fn arg_type(&self, i: usize) -> Cow<'_, FieldType>;

    /// A working object of the body that lives for this driver call: one per row in the row
    /// driver, one per chunk in the vector driver — Go's vector versions create such objects
    /// once per call (e.g. the `WildcardPattern` of `builtinLikeSig.vecEvalInt`) and its row
    /// versions once per row. The body must not depend on what a previous row left in it.
    // glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
    fn scratch<T: 'static>(&self, init: impl FnOnce() -> T) -> RefMut<'_, T>;

    /// Whether this is the vector driver. Only for the places where Go's vector version
    /// differs from its row version in what the user sees (spec D08.1 §3.4 (c), e.g. the
    /// warning text of `builtinCastDecimalAsIntSig`): each driver follows its own Go version.
    // glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
    fn vector(&self) -> bool;
}

/// Storage of [`SigView::scratch`].
#[derive(Default)]
pub struct Scratch(RefCell<Option<Box<dyn Any>>>);

impl Scratch {
    #[inline]
    // glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
    fn get<T: 'static>(&self, init: impl FnOnce() -> T) -> RefMut<'_, T> {
        let mut slot = self.0.borrow_mut();
        if !slot.as_ref().is_some_and(|b| b.is::<T>()) {
            *slot = Some(Box::new(init()));
        }
        RefMut::map(slot, |b| {
            b.as_mut()
                .and_then(|b| b.downcast_mut::<T>())
                .expect("scratch type")
        })
    }
}

/// The row driver's [`SigView`].
pub struct RowSig<'a> {
    f: &'a BuiltinFunc,
    ctx: &'a dyn EvalContext,
    scratch: Scratch,
}

impl<'a> RowSig<'a> {
    /// The view of `f`.
    #[inline(always)]
    // glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
    pub fn new(f: &'a BuiltinFunc, ctx: &'a dyn EvalContext) -> Self {
        RowSig {
            f,
            ctx,
            scratch: Scratch::default(),
        }
    }
}

impl std::ops::Deref for RowSig<'_> {
    type Target = BuiltinFunc;
    #[inline(always)]
    // glue: trait impl
    fn deref(&self) -> &BuiltinFunc {
        self.f
    }
}

impl SigView for RowSig<'_> {
    #[inline(always)]
    // glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
    fn arg_type(&self, i: usize) -> Cow<'_, FieldType> {
        self.f.args[i].get_type(self.ctx)
    }

    #[inline(always)]
    // glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
    fn scratch<T: 'static>(&self, init: impl FnOnce() -> T) -> RefMut<'_, T> {
        self.scratch.get(init)
    }

    #[inline(always)]
    // glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
    fn vector(&self) -> bool {
        false
    }
}

/// The argument types of one vector-driver call, read once per chunk.
pub struct ArgTypes<'a>(SmallVec<[Cow<'a, FieldType>; 4]>);

impl<'a> ArgTypes<'a> {
    /// Reads the argument types of `f`.
    #[inline]
    // glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
    pub fn new(f: &'a BuiltinFunc, ctx: &'a dyn EvalContext) -> Self {
        ArgTypes(f.args.iter().map(|a| a.get_type(ctx)).collect())
    }
}

/// The vector driver's [`SigView`].
pub struct VecSig<'a, 't> {
    f: &'a BuiltinFunc,
    types: &'a [Cow<'t, FieldType>],
    scratch: Scratch,
}

impl<'a, 't> VecSig<'a, 't> {
    /// The view of `f` with the types of this chunk.
    #[inline(always)]
    // glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
    pub fn new(f: &'a BuiltinFunc, types: &'a ArgTypes<'t>) -> Self {
        VecSig {
            f,
            types: &types.0,
            scratch: Scratch::default(),
        }
    }
}

impl std::ops::Deref for VecSig<'_, '_> {
    type Target = BuiltinFunc;
    #[inline(always)]
    // glue: trait impl
    fn deref(&self) -> &BuiltinFunc {
        self.f
    }
}

impl SigView for VecSig<'_, '_> {
    #[inline(always)]
    // glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
    fn arg_type(&self, i: usize) -> Cow<'_, FieldType> {
        Cow::Borrowed(&*self.types[i])
    }

    #[inline(always)]
    // glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
    fn scratch<T: 'static>(&self, init: impl FnOnce() -> T) -> RefMut<'_, T> {
        self.scratch.get(init)
    }

    #[inline(always)]
    // glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
    fn vector(&self) -> bool {
        true
    }
}

/// The arguments of a `lazy` body: evaluated when the body asks, as Go's row versions do.
pub trait Args {
    /// `len(b.args)`.
    // glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
    fn len(&self) -> usize;
    /// Whether there are no arguments.
    // glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
    fn is_empty(&self) -> bool {
        self.len() == 0
    }
    /// `b.args[i].EvalInt(ctx, row)`.
    // glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
    fn int(&mut self, ctx: &dyn EvalContext, i: usize) -> Result<Option<i64>, Error>;
    /// `b.args[i].EvalReal(ctx, row)`.
    // glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
    fn real(&mut self, ctx: &dyn EvalContext, i: usize) -> Result<Option<f64>, Error>;
    /// `b.args[i].EvalString(ctx, row)`.
    // glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
    fn string(&mut self, ctx: &dyn EvalContext, i: usize) -> Result<Option<Cow<'_, [u8]>>, Error>;
    /// `b.args[i].EvalDecimal(ctx, row)`.
    // glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
    fn decimal(&mut self, ctx: &dyn EvalContext, i: usize) -> Result<Option<MyDecimal>, Error>;
}

/// One node of an [`RpnProgram`] (post-order).
#[derive(Debug)]
pub enum RpnNode {
    /// A column of the input chunk, copied (or borrowed) as is.
    ColumnRef {
        /// `Column.Index`.
        index: usize,
    },
    /// A column of the input chunk that Go's `Column.VecEvalXxx` converts: a hybrid
    /// (ENUM/SET/BIT) column read as int or string, or a FLOAT column read as real.
    ColumnConv {
        /// The column.
        expr: ExprRef,
        /// The evaluation type the parent reads (`ETInt`, `ETString` or `ETReal`).
        as_type: EvalType,
    },
    /// A constant: evaluated once per chunk and filled into a column (Go `genVecFromConstExpr`).
    Constant {
        /// The constant.
        expr: ExprRef,
        /// The evaluation type the parent reads.
        as_type: EvalType,
    },
    /// A function call over the last `nargs` results.
    Call {
        /// The function node.
        func: ExprRef,
        /// The number of arguments.
        nargs: usize,
    },
}

/// An expression compiled for the vector driver (N4 §3.4). Immutable, `Send + Sync`.
#[derive(Debug)]
pub struct RpnProgram {
    nodes: Vec<RpnNode>,
    ret: EvalType,
}

/// Per-worker state of vector evaluation: reusable intermediate columns and stack.
#[derive(Default)]
pub struct RpnState {
    pool: Vec<Column>,
    stack: Vec<Slot>,
}

impl std::fmt::Debug for RpnState {
    // glue: trait impl
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("RpnState")
            .field("pool", &self.pool.len())
            .finish()
    }
}

// A temporary column moves in and out of the pool; boxing it would add an allocation.
#[allow(clippy::large_enum_variant)]
enum Slot {
    Input(usize),
    Temp(Column),
}

impl RpnProgram {
    /// Compiles `e` for the vector driver.
    // glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
    pub fn compile(e: &ExprRef) -> RpnProgram {
        let mut nodes = Vec::new();
        let ret = static_eval_type(e);
        compile_into(e, ret, &mut nodes);
        RpnProgram { nodes, ret }
    }

    /// The evaluation type of the result.
    // glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
    pub fn ret_eval_type(&self) -> EvalType {
        self.ret
    }

    /// Evaluates the program on `input` into `result` (Go `VecEvalXxx(ctx, input, result)`).
    // glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
    pub fn eval(
        &self,
        ctx: &dyn EvalContext,
        st: &EvalState,
        rpn: &mut RpnState,
        input: &Chunk,
        result: &mut Column,
    ) -> Result<(), Error> {
        let mut stack = std::mem::take(&mut rpn.stack);
        stack.clear();
        let r = self.eval_inner(ctx, st, rpn, &mut stack, input, result);
        for s in stack.drain(..) {
            if let Slot::Temp(c) = s {
                rpn.pool.push(c);
            }
        }
        rpn.stack = stack;
        r
    }

    // glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
    fn eval_inner(
        &self,
        ctx: &dyn EvalContext,
        st: &EvalState,
        rpn: &mut RpnState,
        stack: &mut Vec<Slot>,
        input: &Chunk,
        result: &mut Column,
    ) -> Result<(), Error> {
        let n = input.num_rows();
        let last = self.nodes.len() - 1;
        for (pos, node) in self.nodes.iter().enumerate() {
            match node {
                RpnNode::ColumnRef { index } => {
                    if pos == last {
                        // The whole expression is a column: Go copies it into the result.
                        let dst = std::mem::replace(result, rt::empty_column());
                        *result = input
                            .column(*index)
                            .copy_reconstruct(input.sel(), Some(dst));
                        return Ok(());
                    }
                    match input.sel() {
                        None => stack.push(Slot::Input(*index)),
                        Some(sel) => {
                            let tmp = rpn.pool.pop();
                            stack.push(Slot::Temp(
                                input.column(*index).copy_reconstruct(Some(sel), tmp),
                            ));
                        }
                    }
                }
                RpnNode::ColumnConv { expr, as_type } => {
                    let c = expr.as_column().expect("ColumnConv holds a Column");
                    if pos == last {
                        return column_conv(ctx, c, *as_type, input, result);
                    }
                    let mut col = rpn.pool.pop().unwrap_or_else(rt::empty_column);
                    let r = column_conv(ctx, c, *as_type, input, &mut col);
                    stack.push(Slot::Temp(col));
                    r?;
                }
                RpnNode::Constant { expr, as_type } => {
                    if pos == last {
                        return rt::fill_constant(ctx, st, expr, *as_type, n, result);
                    }
                    let mut col = rpn.pool.pop().unwrap_or_else(rt::empty_column);
                    let r = rt::fill_constant(ctx, st, expr, *as_type, n, &mut col);
                    stack.push(Slot::Temp(col));
                    r?;
                }
                RpnNode::Call { func, nargs } => {
                    let f = &func
                        .as_scalar_function()
                        .expect("Call node holds a ScalarFunction")
                        .function;
                    let base = stack.len() - nargs;
                    let mut out = if pos == last {
                        None
                    } else {
                        Some(rpn.pool.pop().unwrap_or_else(rt::empty_column))
                    };
                    let r = {
                        let cols: rt::ArgCols<'_> = stack[base..]
                            .iter()
                            .map(|s| match s {
                                Slot::Input(i) => input.column(*i),
                                Slot::Temp(c) => c,
                            })
                            .collect();
                        let dst = match out.as_mut() {
                            Some(c) => c,
                            None => &mut *result,
                        };
                        f.vec_eval(
                            ctx,
                            f.sig.drivers.eval_type().unwrap_or(ETInt),
                            n,
                            &cols,
                            dst,
                        )
                    };
                    for s in stack.drain(base..) {
                        if let Slot::Temp(c) = s {
                            rpn.pool.push(c);
                        }
                    }
                    match out {
                        Some(c) => stack.push(Slot::Temp(c)),
                        None => return r,
                    }
                    r?;
                }
            }
        }
        unreachable!("an RPN program ends with its root")
    }
}

// glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
fn compile_into(e: &ExprRef, as_type: EvalType, nodes: &mut Vec<RpnNode>) {
    match &**e {
        Expr::Column(c) => nodes.push(match column_read(c, as_type) {
            ColumnRead::Copy => RpnNode::ColumnRef {
                index: c.index as usize,
            },
            ColumnRead::Convert => RpnNode::ColumnConv {
                expr: e.clone(),
                as_type,
            },
        }),
        Expr::Constant(_) | Expr::CorrelatedColumn(_) => nodes.push(RpnNode::Constant {
            expr: e.clone(),
            as_type,
        }),
        Expr::ScalarFunction(sf) => {
            let drivers = &sf.function.sig.drivers;
            for (i, a) in sf.function.args.iter().enumerate() {
                let read = drivers
                    .arg_eval_type(i)
                    .unwrap_or_else(|| static_eval_type(a));
                compile_into(a, read, nodes);
            }
            nodes.push(RpnNode::Call {
                func: e.clone(),
                nargs: sf.function.args.len(),
            });
        }
    }
}

/// The evaluation type of `e`'s `RetType` known at build time (a parameter marker's type is
/// fixed when the plan is built, so the field is enough here).
// glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
fn static_eval_type(e: &Expr) -> EvalType {
    match e {
        Expr::Column(c) => c.ret_type.eval_type(),
        Expr::CorrelatedColumn(c) => c.column.ret_type.eval_type(),
        Expr::Constant(c) => c.ret_type.eval_type(),
        Expr::ScalarFunction(f) => f.ret_type.eval_type(),
    }
}

/// How the vector driver reads a column argument.
enum ColumnRead {
    /// Go's `Column.VecEvalXxx` copies the column (`CopyReconstruct`).
    Copy,
    /// Go's `Column.VecEvalXxx` converts it row by row (hybrid, FLOAT).
    Convert,
}

/// Which `Column.VecEvalXxx` branch Go takes when the parent reads `c` as `as_type`.
///
/// Go converts only a hybrid column read as int or string and a FLOAT column read as real;
/// any other read copies the column's storage. A copy whose storage does not hold
/// `as_type` values (a hybrid or FLOAT column read as another type, or a column whose
/// evaluation type differs from `as_type`) would make the signature misread the bytes —
/// Go's function classes never build such a call, so the RPN refuses it here instead of
/// reading float32 as float64 or an ENUM as an int64 (Lucky #82).
// glue: dispatch of Go `Column.VecEvalInt/Real/String` (M-EVAL)
fn column_read(c: &crate::column::Column, as_type: EvalType) -> ColumnRead {
    let tp = c.ret_type.get_type();
    if c.ret_type.hybrid() {
        if as_type == ETInt || as_type == ETString {
            return ColumnRead::Convert;
        }
    } else if tp == tidb_base::mysql::TypeFloat {
        if as_type == ETReal {
            return ColumnRead::Convert;
        }
    } else if c.ret_type.eval_type() == as_type {
        return ColumnRead::Copy;
    }
    panic!(
        "RPN: column {} of type {} (evaluation type {:?}) read as {:?}: Go's Column.VecEval \
         would copy storage that does not hold such values",
        c.index,
        tp,
        c.ret_type.eval_type(),
        as_type
    );
}

/// Go's converting `Column.VecEvalInt/Real/String` (see [`column_read`]).
// glue: dispatch of Go `Column.VecEvalInt/Real/String` (M-EVAL)
fn column_conv(
    ctx: &dyn EvalContext,
    c: &crate::column::Column,
    as_type: EvalType,
    input: &Chunk,
    result: &mut Column,
) -> Result<(), Error> {
    match as_type {
        ETInt => c.vec_eval_int(ctx, input, result),
        ETReal => c.vec_eval_real(ctx, input, result),
        _ => c.vec_eval_string(ctx, input, result),
    }
}
